TEST(canonical_fractions, native_integers) {
    static_assert(std::is_same_v<q32::val<i32::val<2>, i32::val<4>>, q32::val_impl<i32::val<1>, i32::val<2>>>);
    static_assert(std::is_same_v<q64::val<i64::val<2>, i64::val<4>>, q64::val_impl<i64::val<1>, i64::val<2>>>);
    static_assert(std::is_same_v<q32::val<i32::val<-6>, i32::val<-9>>, q32::val_impl<i32::val<2>, i32::val<3>>>);
    static_assert(std::is_same_v<q64::val<i64::val<-6>, i64::val<-9>>, q64::val_impl<i64::val<2>, i64::val<3>>>);
    static_assert(std::is_same_v<q32::val<i32::val<6>, i32::val<-9>>, q32::val_impl<i32::val<-2>, i32::val<3>>>);
    static_assert(std::is_same_v<q64::val<i64::val<6>, i64::val<-9>>, q64::val_impl<i64::val<-2>, i64::val<3>>>);
    static_assert(std::is_same_v<q32::val<i32::val<0>, i32::val<5>>, q32::val_impl<i32::val<0>, i32::val<1>>>);
    static_assert(std::is_same_v<q64::val<i64::val<0>, i64::val<5>>, q64::val_impl<i64::val<0>, i64::val<1>>>);
    static_assert(std::is_same_v<q32::val<i32::val<0>, i32::val<-5>>, q32::val_impl<i32::val<0>, i32::val<1>>>);
    static_assert(std::is_same_v<q64::val<i64::val<0>, i64::val<-5>>, q64::val_impl<i64::val<0>, i64::val<1>>>);
    static_assert(std::is_same_v<q32::val<i32::val<12>, i32::val<4>>, q32::val_impl<i32::val<3>, i32::val<1>>>);
    static_assert(std::is_same_v<q64::val<i64::val<12>, i64::val<4>>, q64::val_impl<i64::val<3>, i64::val<1>>>);
    static_assert(std::is_same_v<q32::val<i32::val<1000000>, i32::val<3000000>>, q32::val_impl<i32::val<1>, i32::val<3>>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<q64::val<i64::val<1000000>, i64::val<3000000>>, q64::val_impl<i64::val<1>, i64::val<3>>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<q32::val<i32::val<-1>, i32::val<1>>, q32::val_impl<i32::val<-1>, i32::val<1>>>);
    static_assert(std::is_same_v<q64::val<i64::val<-1>, i64::val<1>>, q64::val_impl<i64::val<-1>, i64::val<1>>>);
}

