TEST(hex_float_literals, native_integers) {
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"0x1.8p-3", i64>, q64::val_impl<i64::val<3>, i64::val<16>>>);
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"0x1.8p-3", i32>, q32::val_impl<i32::val<3>, i32::val<16>>>);
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"-0x1.1p+4", i64>, q64::val_impl<i64::val<-17>, i64::val<1>>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"-0x1.1p+4", i32>, q32::val_impl<i32::val<-17>, i32::val<1>>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"0x1p-30", i64>, q64::val_impl<i64::val<1>, i64::val<1073741824>>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"0x1p-30", i32>, q32::val_impl<i32::val<1>, i32::val<1073741824>>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"0x3p+0", i64>, q64::val_impl<i64::val<3>, i64::val<1>>>);
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"0x3p+0", i32>, q32::val_impl<i32::val<3>, i32::val<1>>>);
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"0x0p+0", i64>, q64::val_impl<i64::val<0>, i64::val<1>>>);
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"0x0p+0", i32>, q32::val_impl<i32::val<0>, i32::val<1>>>);
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"-0x1.8p+1", i64>, q64::val_impl<i64::val<-3>, i64::val<1>>>);  // NOLINT(whitespace/line_length)
    static_assert(std::is_same_v<aerobus::from_hex_float_t<"-0x1.8p+1", i32>, q32::val_impl<i32::val<-3>, i32::val<1>>>);  // NOLINT(whitespace/line_length)
}
